@app.get("/tasks/list")
def list_tasks(operator: Optional[str] = None, all: bool = False):
    """List tasks with smart filtering.
    By default, returns only:
    - Active tasks (pending/processing)
    - Recently completed tasks (last 10 minutes)
    This dramatically reduces response size for mobile/Tailscale while still
    allowing placeholder polling to detect completions.
    Use ?all=true to get full task history.
    """
    # F2 (Part 2): projection — pulls ONLY the scalar columns the pill renders, NOT
    # result_data (the base64 blob that was 97% of tasks.db). Previously this ran
    # `SELECT * ... ORDER BY created_at DESC` + json.loads on every row (~1s, GIL-held,
    # polled every 2s). Ordering now uses idx_tasks_created_at (no TEMP B-TREE sort).
    # Rows are plain dicts of the projected fields (see TaskDatabase.get_task_list).
    all_tasks = task_db.get_task_list(operator)

    # If all=true, return everything (for debugging/admin)
    if all:
        filtered_tasks = all_tasks
    else:
        # Smart filter: active + recently completed
        from datetime import datetime, timezone, timedelta
        cutoff_time = datetime.now(timezone.utc) - timedelta(minutes=10)

        filtered_tasks = [
            t for t in all_tasks
            if t["status"] in ['pending', 'processing']  # Always show active
            or (
                # Show recently-ended tasks. 'cancelled' is terminal like
                # completed/failed (G2-T8) — without it a just-cancelled task
                # would appear in NEITHER branch and the pill would vanish
                # instantly, which is exactly the "UI lies" bug T8 kills.
                t["status"] in ['completed', 'failed', 'cancelled']
                and t["updated_at"]  # Has update timestamp
                and datetime.fromisoformat(t["updated_at"].replace('Z', '+00:00')) > cutoff_time
            )
        ]

    return {
        "tasks": [{
            "task_id": t["task_id"],
            "task_type": t["task_type"],
            "status": t["status"],
            "progress": t["progress"],
            "created_at": t["created_at"],
            "updated_at": t["updated_at"],
            "result_url": t["result_url"],
            "operator": t["operator"],
            "prompt": t["prompt"][:100] if t["prompt"] else None,
            # G3-T11 (additive): live poll-visible progress line for the pill, and
            # the CU target device. device_id is now its own real column (F2 Part 2),
            # projected directly here — no result_data blob is read. Default mirrors
            # the historical `result_data.get("device_id") or "blackbox"` semantics so
            # the Portal "Live" button (T12) / Android pill (T13) address is unchanged.
            "progress_text": t["progress_text"],
            "device_id": t["device_id"] or "blackbox",
            # G3 live narration: the accumulating model-reasoning transcript the
            # expanded pill renders (scrollable). Bounded (rolling tail) so the
            # polled payload stays small; None/absent for non-CU tasks.
            "reasoning_text": t.get("reasoning_text"),
            # M2 multi-desktop: the CU session this task drives — the key that
            # lets every Live button open the task's OWN desktop
            # (/cu/view/{session_id}) instead of the first streamable session.
            "session_id": t["session_id"],
        } for t in filtered_tasks],
        "total_tasks": len(all_tasks),
        "filtered_count": len(filtered_tasks)
    }

@app.get("/tasks/status/{task_id}")
@app.get("/tasks/{task_id}")  # Alias for MCP compatibility
def get_task_status(task_id: str):
    """Get status of a specific task"""
    task = task_db.get_task(task_id)
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")

    return {
        "task_id": task.task_id,
        "task_type": task.task_type,
        "status": task.status,
        "progress": task.progress,
        "created_at": task.created_at,
        "updated_at": task.updated_at,
        "result_url": task.result_url,
        "result_data": task.result_data,
        "error_message": task.error_message,
        # The owning operator (additive; /tasks/list already carries it). The
        # MCP server's get_media ownership gate reads this for remote callers.
        "operator": task.operator,
        # G3-T11 (additive): the live pill line. device_id stays reachable via the
        # already-returned result_data, so it is not re-surfaced as a top-level key.
        "progress_text": task.progress_text,
        # G3 live narration (additive): the accumulating CU reasoning transcript, so
        # the in-chat placeholder pill — which polls THIS endpoint (not /tasks/list) —
        # can render the scrollable reasoning window for a CU task.
        "reasoning_text": task.reasoning_text
    }

@app.post("/tasks/{task_id}/cancel")
def cancel_one_task(task_id: str):
    """REAL per-task cancellation (G2-T8). Idempotent. Signals the concrete work
    (process-group kill for a CLI agent / cu-stop for Computer Use / cooperative
    flag for media) and marks the row CANCELLED (sticky). Returns a dict the UI
    can render. 404 only for a task that does not exist."""
    from Orchestrator.tasks import cancel_task
    res = cancel_task(task_id)
    if res.get("not_found"):
        raise HTTPException(status_code=404, detail="Task not found")
    return res


@app.post("/tasks/cancel-all")
def cancel_all_stuck_tasks():
    """Cancel all pending/processing tasks. Post-T8 this loops the REAL per-task
    cancel path (signals processes/CU, marks CANCELLED — no longer a cosmetic
    flip to FAILED). Keeps the stuck-task-reaper behavior for handle-less rows."""
    from Orchestrator.tasks import cancel_all_tasks
    return cancel_all_tasks()

# -----------------------------------------------------------------------------
# Recent Snapshots (chronological, newest-first — Android + Portal Timelines)
# -----------------------------------------------------------------------------
# A page is capped so no request can turn back into a whole-volume read.
SNAPSHOT_PAGE_MAX = 500


def _snap_sort_key(snap_id: str) -> tuple:
    """SNAP-YYYYMMDD-NNNNN -> (date, seq): chronological order. (0, 0) if malformed."""
    try:
        parts = snap_id.split('-')
        return (int(parts[1]), int(parts[2]))
    except (ValueError, IndexError):
        return (0, 0)


# Headers/boilerplate lines to skip when extracting preview snippet
_SNIPPET_SKIP_PREFIXES = (
    '===', 'CROSS-FILE', 'Tail', 'COUNT=', 'UFL:', 'Result:',
    'VOLUME TRACKER', 'Next:', 'TBD', '---', '===============',
    'OPERATOR:', 'TYPE:', 'SNAP-', 'TARGET_ID=',
    'Mode:', 'Timestamp:', 'Model:', 'Provider:', 'Tokens:',
    'Session:', 'Voice:', 'Backend:', 'Duration:',
    '[user]', '[assistant]', 'role:', 'content:',
)
# Pattern to find user message in Raw Session Log: [N] timestamp operator=X user: MESSAGE
_SNIPPET_USER_MSG_RX = re.compile(r'\[\d+\]\s+\S+\s+operator=\S+\s+user:\s*(.+)', re.IGNORECASE)


def _snapshot_snippet(chunk: str) -> str:
    """A <=200-char preview from the head of one snapshot's text."""
    # Strategy 1: Find user message in Raw Session Log
    m = _SNIPPET_USER_MSG_RX.search(chunk)
    if m:
        return m.group(1).strip()[:200]
    # Strategy 2: Find first line after "SNAPSHOT BODY" that isn't metadata
    body_idx = chunk.find('SNAPSHOT BODY')
    if body_idx >= 0:
        for line in chunk[body_idx:].split('\n'):
            stripped = line.strip()
            if not stripped or len(stripped) < 15:
                continue
            if any(stripped.startswith(p) for p in _SNIPPET_SKIP_PREFIXES):
                continue
            if stripped.startswith('Kernel') or stripped.startswith('Context') or \
               stripped.startswith('- ') or stripped.startswith('Raw Session'):
                continue
            return stripped[:200]
    return ""


@app.get("/api/snapshots/recent")
def api_snapshots_recent(limit: int = 30, operator: str = "", before: str = ""):
    """Return most recent snapshots in chronological order (newest first).
    Reads from the in-memory snapshot index — lightweight, no volume parsing.
    Returns snap_id, operator, timestamp, type, and a snippet preview.

    `before` (a snap_id) pages back: only snapshots older than it, so a client
    walks the whole ledger one page at a time (the Portal Timeline). Additive
    keys: `has_more` (an older page exists) and `operators` (every operator in
    the index, for a filter list). Each snippet reads at most 4 KB of its own
    snapshot, never the whole volume (audit P04-media-tasks-fx-web-06): Android
    polls this every 10 s while its Timeline is open.
    """
    try:
        from Orchestrator.fossils import load_snapshot_index, VolumeRanges

        index = load_snapshot_index()
        if not index:
            return {"results": [], "count": 0, "has_more": False, "operators": []}

        # Filter by operator if specified
        if operator:
            items = [(sid, meta) for sid, meta in index.items() if meta.get("operator") == operator]
        else:
            items = list(index.items())

        if before:
            cursor = _snap_sort_key(before)
            items = [item for item in items if _snap_sort_key(item[0]) < cursor]

        # Sort by snap_id descending (SNAP-YYYYMMDD-NNNNN — date+seq gives chronological order)
        items.sort(key=lambda item: _snap_sort_key(item[0]), reverse=True)
        limit = max(0, min(limit, SNAPSHOT_PAGE_MAX))
        has_more = len(items) > limit
        items = items[:limit]
        operators = sorted({meta.get("operator", "") for meta in index.values()} - {""})

        # Extract snippets from each snapshot's own byte range
        results = []
        with VolumeRanges() as vol:
            for snap_id, meta in items:
                snippet = ""
                if vol.size:
                    try:
                        start = meta.get("byte_start", 0)
                        end = meta.get("byte_end", start + 4000)
                        # Read up to 4KB to reach past headers into Raw Session Log
                        chunk = vol.read(start, min(end, start + 4000)).decode('utf-8', errors='replace')
                        snippet = _snapshot_snippet(chunk)
                    except Exception:
                        pass

                results.append({
                    "snap_id": snap_id,
                    "operator": meta.get("operator", ""),
                    "timestamp": meta.get("timestamp", ""),
                    "type": meta.get("type", "normal"),
                    "snippet": snippet,
                })

        return {"results": results, "count": len(results), "has_more": has_more,
                "operators": operators}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

# -----------------------------------------------------------------------------
# Single Snapshot Fetch (for Android Timeline detail view)
# -----------------------------------------------------------------------------
@app.get("/fossil/snapshot/{snap_id}")
def fossil_get_snapshot(snap_id: str):
    """Fetch full content of a single snapshot by ID. A short SNAP-<n> (as
    models cite them) resolves to the newest snapshot with that number; the
    response's snap_id is the full id."""
    try:
        from Orchestrator.fossils import get_snapshot_by_id, resolve_snapshot_id
        resolved = resolve_snapshot_id(snap_id)
        result = get_snapshot_by_id(resolved) if resolved else None
        if result is None:
            raise HTTPException(status_code=404, detail=f"Snapshot {snap_id} not found")
        return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

# -----------------------------------------------------------------------------
# Semantic Search Endpoint (for MCP)
# -----------------------------------------------------------------------------
@app.get("/fossil/hybrid")
def fossil_hybrid_search(q: str, operator: str = "", limit: int = 10):
    """Hybrid keyword + semantic search on snapshots (canonical retriever).

    Routes through Orchestrator.retrieval.retrieve(): RRF fusion of keyword +
    semantic candidates, a mild recency tie-break, and MMR diversity. This is no
    longer semantic-only (the old docstring/name were a misnomer) — recency-aware
    hybrid ranking now surfaces recent work near the top. The per-result `score`
    field is retrieve()'s fused/recency score (NOT a raw cosine similarity); it is
    kept under the JSON key `similarity` for response-shape backward compatibility.
    """
    try:
        # Canonical retriever: returns [(snap_id, score), ...] top-k, [] on failure.
        scored = retrieve(q, operator=operator, k=limit)

        if not scored:
            return {"results": [], "message": "No results found or embeddings not available"}

        # Load the index; each result's content is read from its own byte
        # range, not the whole volume.
        from Orchestrator.fossils import VolumeRanges, extract_snapshot_content
        index = load_snapshot_index()

        results = []
        with VolumeRanges() as vol:
            for snap_id, score in scored:
                if snap_id not in index:
                    continue

                meta = index[snap_id]

                # Get snippet of content
                start = meta.get("byte_start", 0)
                end = meta.get("byte_end", 0)
                snippet = ""
                if start < vol.size and end <= vol.size:
                    snap_bytes = vol.read(start, end)
                    snap_text = snap_bytes.decode('utf-8', errors='replace')
                    # M15.3: the 500-char preview is the BODY head (Raw Session Log
                    # onward), not the START/BEACON envelope head. The MCP
                    # search_snapshots / get_context client (and Portal lists) then
                    # see meaningful content, not bookkeeping. The 500-char cut and
                    # the ranked snap_id + similarity fields are unchanged.
                    body = extract_snapshot_content(snap_text)
                    snippet = body[:500] + "..." if len(body) > 500 else body

                results.append({
                    "snap_id": snap_id,
                    "operator": meta.get("operator", "unknown"),
                    "timestamp": meta.get("timestamp", ""),
                    "type": meta.get("type", "normal"),
                    # `similarity` key kept for API compat; value is now the fused
                    # recency-aware retrieve() score, not a raw cosine similarity.
                    "similarity": round(score, 4),
                    "snippet": snippet
                })

        return {
            "query": q,
            "operator": operator or "all",
            "count": len(results),
            "results": results
        }
    except Exception as e:
        print(f"[FOSSIL] Hybrid search error: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))

@app.post("/analyze/audio")
async def analyze_audio(inp: AudioAnalysisIn):
    """Queue audio analysis task - Block 3"""
    # file_path comes from the body (and from the model via analyze_audio); the
    # worker uploads it to the Gemini Files API, so refuse anything that is not
    # an audio file inside Portal/uploads before it is queued.
    try:
        audio_file = resolve_upload_path(inp.file_path, allowed_exts=AUDIO_EXTS)
    except UploadPathError as e:
        raise HTTPException(status_code=400, detail=str(e))
    try:
        task = create_task(
            TaskType.AUDIO_ANALYSIS,
            operator=inp.operator,
            input_file=str(audio_file),
            result_data={"prompt": inp.prompt}
        )
        return {
            "task_id": task.task_id,
            "status": task.status,
            "message": "Audio analysis queued"
        }
    except Exception as e:
        print(f"ERROR: Failed to queue audio analysis: {e}")
        raise HTTPException(status_code=500, detail=str(e))
